import java.util.Arrays;

class Solution {
    public int maximumSaleItems(int[][] items, int budget) {
        int n = items.length;
        
        // Step 1: Precompute free copies generated by activating item i
        int[] freebiesCount = new int[n];
        for (int i = 0; i < n; i++) {
            int f1 = items[i][0];
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && items[j][0] % f1 == 0) {
                    count++;
                }
            }
            freebiesCount[i] = count;
        }

        // dp[b] stores the max item copies achievable using exactly/at most 'b' budget 
        // using initial activations (first copy of items).
        int[] dp = new int[budget + 1];
        Arrays.fill(dp, 0);

        // 0/1 Knapsack to activate items
        for (int i = 0; i < n; i++) {
            int price = items[i][1];
            int gain = 1 + freebiesCount[i]; // 1 purchased + free copies
            
            for (int b = budget; b >= price; b--) {
                dp[b] = Math.max(dp[b], dp[b - price] + gain);
            }
        }

        // Step 2: Find the minimum price among all items to spend remaining budget on extra copies
        int minPrice = Integer.MAX_VALUE;
        for (int[] item : items) {
            minPrice = Math.min(minPrice, item[1]);
        }

        // Step 3: Combine initial activations with buying additional cheap copies
        int maxTotalCopies = 0;
        for (int b = 0; b <= budget; b++) {
            int remainingBudget = budget - b;
            int extraCopies = remainingBudget / minPrice;
            maxTotalCopies = Math.max(maxTotalCopies, dp[b] + extraCopies);
        }

        return maxTotalCopies;
    }
}